pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    function testFuzz_property(address from, uint256 v, uint256 n) public {
        uint256 len = bound(n, 0, 8);

        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(new Reverter());
        }

        address caddress = address(0);
        if (len > 0) {
            caddress = tos[0];
        } else {
            caddress = address(new Reverter());
        }

        bool ok;
        try c.transfer(from, caddress, tos, uint256(v)) {
            ok = true;
        } catch {
            ok = false;
        }

        if (len > 0) {
            assertTrue(ok == false);
        } else {
            assertTrue(ok == false);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
